#!/usr/bin/env python3
"""dq-check: rule-driven data-quality checker.

Usage:
    dq-check DATA.csv RULES.yaml [--format json|text]

Exit codes:
    0  no violations
    1  usage / configuration error (e.g. unknown rule type)
    2  violations found
"""
import argparse
import csv
import json
import re
import sys
from collections import Counter
from datetime import date

try:
    import yaml
except ImportError:
    sys.exit("error: PyYAML is required (pip install pyyaml)")


def load_rules(path):
    """Load and validate rules from a YAML file."""
    with open(path) as f:
        doc = yaml.safe_load(f) or {}
    rules = doc.get("rules")
    if not rules or not isinstance(rules, list):
        raise ValueError(f"no 'rules' list found in {path}")
    known = {"not_null", "unique", "regex", "range", "allowed_values",
             "cross_field"}
    validated = []
    for rule in rules:
        rtype = rule.get("type")
        if rtype not in known:
            raise ValueError(
                f"unknown rule type {rtype!r} for rule "
                f"{rule.get('name', '<unnamed>')!r}; expected one of: "
                + ", ".join(sorted(known)))
        if not rule.get("name"):
            raise ValueError(f"rule of type {rtype!r} is missing 'name'")
        validated.append(rule)
    return validated


def _num(value):
    return float(value)


def _as_date(value):
    try:
        return date.fromisoformat(str(value))
    except ValueError:
        return str(value)  # fall back to lexicographic compare


_OPS = {
    ">=": lambda a, b: a >= b,
    ">": lambda a, b: a > b,
    "<=": lambda a, b: a <= b,
    "<": lambda a, b: a < b,
    "==": lambda a, b: a == b,
    "!=": lambda a, b: a != b,
}


def check_rule(rule, rows):
    """Return the number of rows violating one rule."""
    rtype = rule["type"]

    if rtype == "not_null":
        col = rule["column"]
        return sum(1 for r in rows if r.get(col) is None or r[col] == "")

    if rtype == "unique":
        col = rule["column"]
        counts = Counter(r.get(col, "") for r in rows)
        return sum(c - 1 for c in counts.values() if c > 1)

    if rtype == "regex":
        col, pattern = rule["column"], re.compile(rule["pattern"])
        return sum(1 for r in rows
                   if r.get(col) not in (None, "")
                   and not pattern.fullmatch(str(r[col])))

    if rtype == "range":
        col, lo, hi = rule["column"], rule.get("min"), rule.get("max")

        def bad(v):
            if v in (None, ""):
                return False
            n = _num(v)
            if lo is not None and n < lo:
                return True
            if hi is not None and n > hi:
                return True
            return False

        return sum(1 for r in rows if bad(r.get(col)))

    if rtype == "allowed_values":
        col, allowed = rule["column"], set(map(str, rule["values"]))
        return sum(1 for r in rows
                   if str(r.get(col)) not in allowed)

    if rtype == "cross_field":
        left, right = rule["left"], rule["right"]
        op = _OPS[rule["operator"]]
        return sum(1 for r in rows
                   if r.get(left) not in (None, "")
                   and r.get(right) not in (None, "")
                   and not op(_as_date(r[left]), _as_date(r[right])))

    raise ValueError(f"unknown rule type {rtype!r}")  # unreachable


def run(csv_path, rules_path):
    rules = load_rules(rules_path)
    with open(csv_path, newline="") as f:
        rows = list(csv.DictReader(f))
    return [(rule["name"], check_rule(rule, rows)) for rule in rules]


def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="dq-check", description="Rule-driven data-quality checker")
    parser.add_argument("csv_file", help="CSV data file to check")
    parser.add_argument("rules_file", help="YAML file with rules")
    parser.add_argument("--format", choices=("json", "text"),
                        default="text", help="output format")
    args = parser.parse_args(argv)

    try:
        results = run(args.csv_file, args.rules_file)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    counts = dict(results)
    total = sum(counts.values())

    if args.format == "json":
        print(json.dumps({"total": total, "rules": counts}, indent=2))
    else:
        for name, count in results:
            print(f"RULE {name}: {count} violations")
        print(f"TOTAL: {total} violations across {len(counts)} rules")

    return 2 if total else 0


if __name__ == "__main__":
    sys.exit(main())

